node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Search for messages to +1-347-555-0169 on 2026-09-01
const msgs = db.prepare(\"SELECT * FROM ts_messages WHERE recipient_phone_number LIKE '%347%555%0169%' AND created_at LIKE '2026-09-01%'\").all();
console.log('Messages to +1-347-555-0169 on 2026-09-01:');
msgs.forEach(m => console.log(JSON.stringify(m, null, 2)));

if (msgs.length === 0) {
  // Try broader search
  console.log('\n--- Broader search: any message with that phone number ---');
  const all = db.prepare(\"SELECT * FROM ts_messages WHERE recipient_phone_number LIKE '%347%555%0169%' OR sender_phone_number LIKE '%347%555%0169%'\").all();
  all.forEach(m => console.log(JSON.stringify(m, null, 2)));

  if (all.length === 0) {
    console.log('\n--- Searching for cleaning-related messages ---');
    const cleaning = db.prepare(\"SELECT * FROM ts_messages WHERE content LIKE '%clean%' OR content LIKE '%apartment%'\").all();
    cleaning.forEach(m => console.log(JSON.stringify(m, null, 2)));
  }
}
"

